#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    double averageWaitingTime(vector<vector<int>>& customers) {
        long long curr_time = 0;
        long long total_wait = 0;
        for (const auto& c : customers) {
            curr_time = max(curr_time, (long long)c[0]) + c[1];
            total_wait += curr_time - c[0];
        }
        return (double)total_wait / customers.size();
    }
};

class Solution {
    public double averageWaitingTime(int[][] customers) {
        long currTime = 0;
        long totalWait = 0;
        for (int[] c : customers) {
            currTime = Math.max(currTime, (long)c[0]) + c[1];
            totalWait += currTime - c[0];
        }
        return (double)totalWait / customers.length;
    }
}

/**
 * @param {number[][]} customers
 * @return {number}
 */
var averageWaitingTime = function(customers) {
    let currTime = 0;
    let totalWait = 0;
    for (const [arrival, time] of customers) {
        currTime = Math.max(currTime, arrival) + time;
        totalWait += currTime - arrival;
    }
    return totalWait / customers.length;
};
